def node_of(hole):
    """hole = ('L', col, row) | ('R', col, row) | ('rail', name, col)"""
    if hole[0] == 'rail':
        return ('rail', hole[1])
    return (hole[0], hole[1])

class Circuit(object):
    """resistor network on the breadboard, solved by nodal analysis."""

    def __init__(self):
        self.res = {}
        self.lead = {}

    def nodes(self):
        s = set()
        for h1, h2, _ in self.res.values():
            s.add(node_of(h1))
            s.add(node_of(h2))
        for h in self.lead.values():
            if h:
                s.add(node_of(h))
        return sorted(s, key=lambda t: (str(t[0]), str(t[1])))

    def solve(self, probe_loaded=True):
        """return (V_probe, V_of_node dict, I_supply) or None if not measurable."""
        hv, hg = (self.lead.get('vc'), self.lead.get('gnd'))
        if not hv or not hg:
            return None
        nv, ng = (node_of(hv), node_of(hg))
        if nv == ng:
            return 'short'
        nodes = self.nodes()
        idx = {n: i for i, n in enumerate(nodes)}
        n = len(nodes)
        G = [[0.0] * n for _ in range(n)]
        I = [0.0] * n

        def stamp(a, b, g):
            ia, ib = (idx[a], idx[b])
            G[ia][ia] += g
            G[ib][ib] += g
            G[ia][ib] -= g
            G[ib][ia] -= g
        for h1, h2, R in self.res.values():
            a, b = (node_of(h1), node_of(h2))
            if a == b:
                continue
            stamp(a, b, 1.0 / max(R, 1e-09))
        hp = self.lead.get('probe')
        if hp and probe_loaded:
            a = node_of(hp)
            if a != ng:
                stamp(a, ng, 1.0 / ADC_RIN)
        for a in nodes:
            if a != ng:
                G[idx[a]][idx[a]] += 1.0 / R_LEAK
        for fixed, val in ((nv, VCC), (ng, 0.0)):
            i = idx[fixed]
            for j in range(n):
                G[i][j] = 0.0
            G[i][i] = 1.0
            I[i] = val
        V = gauss(G, I)
        if V is None:
            return None
        volt = {nd: V[idx[nd]] for nd in nodes}
        isup = 0.0
        for h1, h2, R in self.res.values():
            a, b = (node_of(h1), node_of(h2))
            if a == nv and b != nv:
                isup += (volt[a] - volt[b]) / R
            elif b == nv and a != nv:
                isup += (volt[b] - volt[a]) / R
        if hp and probe_loaded and (node_of(hp) == nv):
            isup += volt[nv] / ADC_RIN
        if isup > VCC / R_SHORT:
            return 'short'
        vp = volt[node_of(hp)] if hp else None
        return (vp, volt, isup)

def gauss(A, b):
    n = len(b)
    M = [row[:] + [b[i]] for i, row in enumerate(A)]
    for c in range(n):
        p = max(range(c, n), key=lambda r: abs(M[r][c]))
        if abs(M[p][c]) < 1e-18:
            return None
        M[c], M[p] = (M[p], M[c])
        pv = M[c][c]
        for r in range(n):
            if r == c:
                continue
            f = M[r][c] / pv
            if f:
                for k in range(c, n + 1):
                    M[r][k] -= f * M[c][k]
    return [M[i][n] / M[i][i] for i in range(n)]

class Device(object):
    """one micro:bit.  Ideal linear mapping 0..Vc -> 0..1023 plus a small,
    device specific integral non-linearity and read noise."""

    def __init__(self, k, seed):
        rng = random.Random(1000 * seed + k)
        self.k = k
        self.gain = 1.0 + rng.uniform(-0.0012, 0.0012)
        self.off = rng.uniform(-0.45, 0.45)
        self.a = [rng.uniform(-1.6, 1.6), rng.uniform(-1.2, 1.2), rng.uniform(-0.9, 0.9)]
        self.noise = 0.3
        self.rng = rng
        self.dead = False

    def inl(self, u):
        return self.a[0] * math.sin(math.pi * u) + self.a[1] * math.sin(2 * math.pi * u) + self.a[2] * math.sin(3 * math.pi * u)

    def read(self, v):
        u = max(0.0, min(1.0, v / VCC))
        x = ADC_MAX * u * self.gain + self.off + self.inl(u) + self.rng.gauss(0.0, self.noise)
        return int(max(0, min(ADC_MAX, math.floor(x + 0.5))))

class World(object):

    def __init__(self, seed=None):
        seed = random.randrange(1 << 30) if seed is None else seed
        self.seed = seed
        self.rng = random.Random(seed)
        self.cir = Circuit()
        self.devices = [Device(k, seed) for k in range(3)]
        self.active = 0
        self.cells_free = 6
        self.cell_hand = 0
        self.cells = [0, 0, 0]
        self.batt_in = [False] * 3
        self.switch = [False] * 3
        self.spare_used = False
        self.jump = dict((i, {'hdr': None, 'hole': None}) for i in WIRES)
        self.msg = ''
        self.value = {}
        for pk, items in PACKS.items():
            for cid, nom, kind, col in items:
                self.value[cid] = nom * (1.0 + self.rng.uniform(-TOL, TOL))
        self.placed = {}
        self.taken = set()

    @property
    def power(self):
        """a kit runs only with two cells in its holder, the plug in and the
        slide switch on."""
        k = self.active
        return self.cells[k] == 2 and self.batt_in[k] and self.switch[k]

    @power.setter
    def power(self, v):
        """convenience used by the verification harness: set up (or shut down)
        every kit at once, exactly as if all six cells had been fitted."""
        for k in range(3):
            if v:
                take = min(2 - self.cells[k], self.cells_free)
                self.cells_free -= take
                self.cells[k] += take
            self.batt_in[k] = bool(v)
            self.switch[k] = bool(v)

    def cells_total(self):
        """six cells all told, wherever they happen to be."""
        return self.cells_free + sum(self.cells) + self.cell_hand

    def load_cell(self, k):
        """put one of the loose cells into holder k."""
        if self.cells_free <= 0 or self.cells[k] >= 2:
            return False
        self.cells_free -= 1
        self.cells[k] += 1
        return True

    def unload_cell(self, k):
        if self.cells[k] <= 0:
            return False
        self.cells[k] -= 1
        self.cells_free += 1
        return True

    @property
    def dev(self):
        return self.devices[self.active]

    def place(self, cid, h1, h2):
        self.placed[cid] = (h1, h2)
        self.cir.res[cid] = (h1, h2, self.value[cid])

    def remove(self, cid):
        self.placed.pop(cid, None)
        self.cir.res.pop(cid, None)

    def set_lead(self, which, hole):
        self.cir.lead[which] = hole

    def free_wire(self):
        for i in WIRES:
            j = self.jump[i]
            if not j['hdr'] and (not j['hole']):
                return i
        return None

    def wire_at_hdr(self, col, row):
        for i in WIRES:
            j = self.jump[i]
            if j['hdr'] and j['hdr'][0] == col and (j['hdr'][1] == row):
                return i
        return None

    def roles(self):
        """the V row is the supply, the G row the reference, the S row of
        column k is pin Pk."""
        r = {'vc': None, 'gnd': None, 'pin': {}}
        for i in WIRES:
            j = self.jump[i]
            if not j['hdr'] or not j['hole']:
                continue
            if j['hdr'][1] == 'V':
                r['vc'] = j['hole']
            elif j['hdr'][1] == 'G':
                r['gnd'] = j['hole']
            else:
                r['pin'][j['hdr'][0]] = j['hole']
        return r

    def measure(self, which='A'):
        """press button A: returns the integer the micro:bit scrolls, or a
        status string ('off', 'nowire', 'short', 'dead')."""
        if self.dev.dead:
            return 'dead'
        if not self.power:
            return 'off'
        R = self.roles()
        if not R['vc']:
            return 'novc'
        if not R['gnd']:
            return 'nognd'
        pin = BTN_PIN.get(which or 'A', 0)
        hp = R['pin'].get(pin)
        self.cir.lead = {'vc': R['vc'], 'gnd': R['gnd'], 'probe': hp}
        r = self.cir.solve()
        if r is None:
            return 'nowire'
        if r == 'short':
            self.dev.dead = True
            return 'short'
        vp, volt, isup = r
        # an input with nothing on it is not an error on real hardware: it
        # floats, and the converter returns whatever the leakage leaves
        if hp is None:
            return self.dev.read(self.rng.uniform(0.0, 0.06))
        if vp is None:
            return 'nowire'
        return self.dev.read(vp)
