    def _chip_label(self, cid, nom, kind):
        if kind == 'tube':
            return '??'
        if nom >= 1000:
            return '%g k' % (nom / 1000.0)
        return '%g' % nom

    def _fit(self):
        W, H = (self.cv.winfo_width(), self.cv.winfo_height())
        if W < 30 or H < 30 or getattr(self, '_view_touched', False):
            return
        x0, y0, x1, y1 = (24.0, 24.0, BX + (NCOL + 2.6) * P, BY + 18.4 * P)
        self.zoom = min(W / (x1 - x0), H / (y1 - y0)) * 0.98
        self.pan = [(W - (x1 - x0) * self.zoom) / 2.0 - x0 * self.zoom, (H - (y1 - y0) * self.zoom) / 2.0 - y0 * self.zoom]

    def S(self, x, y):
        return (x * self.zoom + self.pan[0], y * self.zoom + self.pan[1])

    def inv(self, px, py):
        return ((px - self.pan[0]) / self.zoom, (py - self.pan[1]) / self.zoom)

    def nearest_hole(self, px, py, rmax=None):
        if rmax is None:
            rmax = max(P * 0.62, 14.0 / self.zoom)
        x, y = self.inv(px, py)
        best, bd = (None, 1000000000.0)
        for h in self.holes:
            hx, hy = hole_pos(h)
            d = (hx - x) ** 2 + (hy - y) ** 2
            if d < bd:
                best, bd = (h, d)
        return best if bd <= rmax * rmax else None

    def _static_key(self):
        w = self.w
        return (round(self.zoom, 4), round(self.pan[0], 2), round(self.pan[1], 2), self.cv.winfo_width(), self.cv.winfo_height(), w.active, tuple(w.cells), w.cells_free, tuple(w.batt_in), tuple(w.switch), tuple(sorted(w.placed.items())), tuple(sorted(((k, str(v)) for k, v in w.cir.lead.items()))), self.carry, self.pending, w.dev.dead, self.carry_cell)

